INSERT OR IGNORE INTO "Page" ("id", "slug", "title", "content", "metaTitle", "metaDesc", "parent", "sortOrder", "archiveDate", "published", "gallerySlug", "createdAt", "updatedAt", "authorId") VALUES ('legacypage_09f7ee73081ba1a66a742c9f', 'rueckblick/familienkreis/10-jahre-familienkreis-2009-2019', '10 Jahre Familienkreis (2009-2019)', 'Am 08. Februar 2019 trafen sich 26 Mitglieder vom Familienkreis und feierten auf der Kolpingwiese bei Glühweinglühen ihr 10 jähriges Bestehen. Bettina Schach vom Leitungsteam dankte den Teilnehmern für ihr Kommen und gab der Hoffnung Ausdruck, dass die Zukunft der Kolpingsfamilie vorerst gesichert ist. Auch Wolfgang Rörig der damalige Vorsitzende bedankte sich bei den Teilnehmern, dass sie seine Idee umgesetzt haben.

![familienkr 10](/images/legacy-v2/89/894927683d28fbd04643dd65ee30b4a1-w1600-q78.webp)', NULL, 'Am 08. Februar 2019 trafen sich 26 Mitglieder vom Familienkreis und feierten auf der Kolpingwiese bei Glühweinglühen ihr 10 jähriges Bestehen. Bettina Schach vom Leitungsteam dankte den Teilnehmern für ihr Kommen und gab der Hoffnung Ausdru', 'rueckblick/familienkreis', 0, '2019-07-03T00:00:00.000Z', 1, NULL, '2019-07-03T00:00:00.000Z', '2019-07-03T00:00:00.000Z', NULL);
