INSERT OR IGNORE INTO "Page" ("id", "slug", "title", "content", "metaTitle", "metaDesc", "parent", "sortOrder", "archiveDate", "published", "gallerySlug", "createdAt", "updatedAt", "authorId") VALUES ('legacypage_0818f21b1062b87870244d2b', 'rueckblick/jahresprogramm/2019-07-03-maiandacht-2019', 'Maiandacht 2019', 'Am Freitag, 24. Mai feierten wir an der Mariengrotte, die von der Kolpingsfamilie 1973 erbaut wurde, eine Maiandacht mit unserem Präses Pfr. Werner Kilian. Musikalisch wurde die Feier von unserer Blaskapelle gestaltet.

Anschließend trafen wir uns in gemütlicher Runde im Pfarrheim bei verschiedenen leckeren Bowlen.

![Maiandacht1](/images/legacy-v2/47/47f031bbe897840b6c0dd282eee68789-w1600-q78.webp)

Traditionell trafen wir uns neben der Kirche, an der Mariengrotte.

![Maiandacht2](/images/legacy-v2/c3/c311d2180edba7a35f2ae57feee336f8-w1600-q78.webp)

Musikalisch ist unsere Blaskapelle immer dabei.', NULL, 'Am Freitag, 24. Mai feierten wir an der Mariengrotte, die von der Kolpingsfamilie 1973 erbaut wurde, eine Maiandacht mit unserem Präses Pfr. Werner Kilian. Musikalisch wurde die Feier von unserer Blaskapelle gestaltet. Anschließend trafen w', 'rueckblick/jahresprogramm', 0, '2019-07-03T00:00:00.000Z', 1, NULL, '2019-07-03T00:00:00.000Z', '2019-07-03T00:00:00.000Z', NULL);
