INSERT OR IGNORE INTO "Page" ("id", "slug", "title", "content", "metaTitle", "metaDesc", "parent", "sortOrder", "archiveDate", "published", "gallerySlug", "createdAt", "updatedAt", "authorId") VALUES ('legacypage_77c6a1f25c141e1c6297db4d', 'rueckblick/jahresprogramm/2019-07-12-klostermauerfest-2019', 'Klostermauerfest 2019', 'Am Samstag den 6. Juli fand auf dem historischen Gelände des ehemaligen Zisterzienser-Klosters, gleich neben der damaligen Zehntscheune, das traditionelle Klostermauerfest statt.

Passend dazu gab es neben kulinarischen Köstlichkeiten aus der Klosterküche auch frisches Fassbier aus der Klosterbrauerei Andechs.

Für die musikalische Untermalung sorgte die Kolpingskapelle unter der Leitung von Ramona Cornacchione.

![Klostermauer2019](/images/legacy-v2/36/36e7b80a521ad31e59b0d0b6802c8793-w1600-q78.webp)

Trotz heißen Temperaturen und Schulferien ein gelungenes Fest auf der Kolpingwiese.', NULL, 'Am Samstag den 6. Juli fand auf dem historischen Gelände des ehemaligen Zisterzienser-Klosters, gleich neben der damaligen Zehntscheune, das traditionelle Klostermauerfest statt. Passend dazu gab es neben kulinarischen Köstlichkeiten aus de', 'rueckblick/jahresprogramm', 0, '2019-07-12T00:00:00.000Z', 1, NULL, '2019-07-12T00:00:00.000Z', '2019-07-12T00:00:00.000Z', NULL);
