INSERT OR IGNORE INTO "Page" ("id", "slug", "title", "content", "metaTitle", "metaDesc", "parent", "sortOrder", "archiveDate", "published", "gallerySlug", "createdAt", "updatedAt", "authorId") VALUES ('legacypage_fa5691ed694ea5f62d32b632', 'rueckblick/jahresprogramm/2020-06-14-fronleichnamsfest-auf-der-kolpingwiese-ramsen', 'Fronleichnamsfest auf der Kolpingwiese Ramsen', 'Am Sonntag,  14.06.2020 fand auf der Kolpingwiese in Ramsen ein Fronleichnamsgottesdienst durch Pater Clifford statt. Bei bedecktem Himmel aber trocken, kamen viele Christen aus Ramsen und Umgebung, um unter freiem Himmel eine hlg. Messe zu feiern. Die verantwortlichen aus Ramsen stellten einen überdachten Altar auf und sorgten dafür, dass alle Teilnehmer einen Sitzplatz mit den vorgegebenen  Abständen hatten. Auch die Organistin Frau Probst und Herr Reuther mit seinem Sologesang trugen zum guten Gelingen bei.

![Fronleichnam 2 2020 klein](/images/legacy-v2/16/161af8c9e1425e42dc35ba5c46d65d8f-w1600-q78.webp)

![Fronleichnam 2020 klein](/images/legacy-v2/d4/d4b7fbbb61de557c61f7f99c29a82e72-w1600-q78.webp)

![Fronleichnam 4 2020 klein](/images/legacy-v2/f8/f805a246208e82cfe94ab104f3785e3b-w1600-q78.webp)', NULL, 'Am Sonntag, 14.06.2020 fand auf der Kolpingwiese in Ramsen ein Fronleichnamsgottesdienst durch Pater Clifford statt. Bei bedecktem Himmel aber trocken, kamen viele Christen aus Ramsen und Umgebung, um unter freiem Himmel eine hlg. Messe zu ', 'rueckblick/jahresprogramm', 0, '2020-06-14T00:00:00.000Z', 1, NULL, '2020-06-14T00:00:00.000Z', '2020-06-14T00:00:00.000Z', NULL);
