INSERT OR IGNORE INTO "Page" ("id", "slug", "title", "content", "metaTitle", "metaDesc", "parent", "sortOrder", "archiveDate", "published", "gallerySlug", "createdAt", "updatedAt", "authorId") VALUES ('legacypage_5ccd7896304aae30787449e1', 'rueckblick/jahresprogramm/2020-12-20-lebendiger-adventskalender', 'Lebendiger Adventskalender', 'Wir beteiligten uns im Dezember 2020 am lebendigen Adventskalender der Pfarrei hlg. Lukas.

Am Sonntag, 20. Dezember gestalteten wir ein Fenster am Jugendraum. Dabei wurde von Sebastian Sattler die Geschichte vom krummen Tannenbaum vorgelesen und gemeinsam das "Vater Unser" gebetet. Sebastian und Frau Fehrenbach bedankten sich bei den Anwesenden und wünschten ein frohes Weihnachtsfest und Gesundheit für alle. Weihnachtslieder kamen aus dem Lautsprecher

![Adventskalender 1](/images/legacy-v2/39/39c5ebebba15d47a3677cfdb8e17eb86-w1600-q78.webp)

Ein ansprechendes Adventskalender - Fenster von der Kolpingsfamilie Ramsen gestaltet.

![Adventskalender 2](/images/legacy-v2/5d/5d11690418c36d960546c74e67588529-w1600-q78.webp)

Den Hygienevorschriften entsprechend lauschten die Teilnehmer auf Abstand und mit Mundschutz den Vortragenden.', NULL, 'Wir beteiligten uns im Dezember 2020 am lebendigen Adventskalender der Pfarrei hlg. Lukas. Am Sonntag, 20. Dezember gestalteten wir ein Fenster am Jugendraum. Dabei wurde von Sebastian Sattler die Geschichte vom krummen Tannenbaum vorgelese', 'rueckblick/jahresprogramm', 0, '2020-12-20T00:00:00.000Z', 1, NULL, '2020-12-20T00:00:00.000Z', '2020-12-20T00:00:00.000Z', NULL);
