INSERT OR IGNORE INTO "Page" ("id", "slug", "title", "content", "metaTitle", "metaDesc", "parent", "sortOrder", "archiveDate", "published", "gallerySlug", "createdAt", "updatedAt", "authorId") VALUES ('legacypage_888123544b00097159ccf096', 'rueckblick/jahresprogramm/2021-06-02-die-e-bikegruppe-auch-in-coronazeiten-unterwegs', 'Die E-Bikegruppe auch in Coronazeiten unterwegs', 'Die erste E-Bike-Tour für 2021 ging bei herrlichem Wetter am 01. Juni von Ramsen übers Göllheimer Häuschen, Dreisen, Weitersweiler, Bolanden nach Kirchheimbolanden. Der Rückweg führte über Marnheim, Albisheim Pfrimm, Biedesheim, Lautersheim, Ebertsheim, durchs Eistal nach Ramsen. Bei 930 Höhenmetern fuhren wir ca. 62 Kilometer.

![Ebike 01.06.2021](/images/legacy-v2/61/6152ebeb82a163470ca9ba4a00a0c408-w1600-q78.webp)', NULL, 'Die erste E-Bike-Tour für 2021 ging bei herrlichem Wetter am 01. Juni von Ramsen übers Göllheimer Häuschen, Dreisen, Weitersweiler, Bolanden nach Kirchheimbolanden. Der Rückweg führte über Marnheim, Albisheim Pfrimm, Biedesheim, Lautersheim', 'rueckblick/jahresprogramm', 0, '2021-06-02T00:00:00.000Z', 1, NULL, '2021-06-02T00:00:00.000Z', '2021-06-02T00:00:00.000Z', NULL);
