INSERT OR IGNORE INTO "Page" ("id", "slug", "title", "content", "metaTitle", "metaDesc", "parent", "sortOrder", "archiveDate", "published", "gallerySlug", "createdAt", "updatedAt", "authorId") VALUES ('legacypage_fd3899a26317e3bf19290e9f', 'rueckblick/jahresprogramm/2021-09-19-die-e-bikegruppe-der-kf', 'Die E-Bikegruppe der KF', 'Bei herrlichem Wetter wurde wieder eine Fahrt mit der E-Bikegruppe durchgeführt. Zunächst ging es hinter dem Kleehof über die mittlerweile bekannte Berg und Talstrecke Richtung Süden. Nach der Autobahn, bergab zum Isenachweiher. Nach einer kurzen Rast kamen wir ins Bad Dürkheimer Tal. Die Mittagspause legten wir im Waldschlösschen ein. Nach einer kräftigen Stärkung ging die Fahrt weiter über Bad Dürkheim an der Haardt entlang nach Grünstadt. Nach einer Pause fuhren wir dann durchs Eistal wieder nach Ramsen.

Die Gesamtfahrstecker wurde mit 58 Kilometer gemessen. Starke Leistung.

![Ebike 07.09.2021 1](/images/legacy-v2/74/74b2adc55bde546b8ac879bd2bab0ff6-w1600-q78.webp)

Das Gruppenfoto am Isenachweiher haben wir für unsere erkrankte Gründerin Hildegard gemacht. Wir wünschen Dir "Gute Besserung".', NULL, 'Bei herrlichem Wetter wurde wieder eine Fahrt mit der E-Bikegruppe durchgeführt. Zunächst ging es hinter dem Kleehof über die mittlerweile bekannte Berg und Talstrecke Richtung Süden. Nach der Autobahn, bergab zum Isenachweiher. Nach einer ', 'rueckblick/jahresprogramm', 0, '2021-09-19T00:00:00.000Z', 1, NULL, '2021-09-19T00:00:00.000Z', '2021-09-19T00:00:00.000Z', NULL);
