INSERT OR IGNORE INTO "Page" ("id", "slug", "title", "content", "metaTitle", "metaDesc", "parent", "sortOrder", "archiveDate", "published", "gallerySlug", "createdAt", "updatedAt", "authorId") VALUES ('legacypage_29b0f61cf8facb969da56f98', 'rueckblick/jahresprogramm/2021-10-24-wiesenfest-2021', 'Wiesenfest 2021', 'Am Sonntag, 24. Oktober 2021 feierten wir zum ersten mal das Wiesenfest auf der Kolpingwiese in Ramsen.

Nachdem durch Corona viele Veranstaltungen ausfallen mußten, haben die Besucher sich über dieses Angebot sehr gefreut. Bei wünderschönem Herbstwetter konnte man die Freude regelrecht spüren.

In der Mittagszeit spielte unsere Blaskapelle zur Unterhaltung.

![Wiesenfest21 02](/images/legacy-v2/f1/f1f75f2a05673ef9ce4e62f9795b0601-w1600-q78.webp)![Wiesenfest21 01](/images/legacy-v2/c9/c9e7d90923583555ec727f294d381718-w1600-q78.webp)', NULL, 'Am Sonntag, 24. Oktober 2021 feierten wir zum ersten mal das Wiesenfest auf der Kolpingwiese in Ramsen. Nachdem durch Corona viele Veranstaltungen ausfallen mußten, haben die Besucher sich über dieses Angebot sehr gefreut. Bei wünderschönem', 'rueckblick/jahresprogramm', 0, '2021-10-24T00:00:00.000Z', 1, NULL, '2021-10-24T00:00:00.000Z', '2021-10-24T00:00:00.000Z', NULL);
