INSERT OR IGNORE INTO "Page" ("id", "slug", "title", "content", "metaTitle", "metaDesc", "parent", "sortOrder", "archiveDate", "published", "gallerySlug", "createdAt", "updatedAt", "authorId") VALUES ('legacypage_e7dd40d5921ff8156aee8669', 'rueckblick/jahresprogramm/2021-12-20-adventsfeier-2021', 'Adventsfeier 2021', 'Im Rahmen der Aktion "Lebendiger Adventskalender" der Pfarrei Heiliger Lukas, feierten wir unser Adventsfest am Sonntag, 19. Dezember auf der Kolpingwiese.

Erika Maier hat unser Fenster am Jugendraum wunderschön gestaltet.

Karin Becker las die Geschichte vom Bleistift vor und Sebastian Sattler ging in seinen abschließenden Ausführungen auf diese Geschichte ein, um sie mit unserem Alltag zu vergleichen. Sebastian begleitete die gesungenen Weihnachtslieder auf seiner Gitarre.

Anschließend gab es Coronabedingt mit Abstand, kostenlos Kinderpunsch und Glühwein.

In der Spendenkasse waren 227 Euro, die wir noch aufrunden werden. Der Erlös soll den Menschen im Ahrtal zu Gute kommen.

![Adventsfeier 21 02](/images/legacy-v2/08/08909b7c88c2e5c266a5ab65af795fde-w1600-q78.webp)

Erika vor Ihrem geschmückten Adventsfenster

![Adventsfeier 21 01](/images/legacy-v2/b8/b8a182186bd1872c6679b2ea208b9191-w1600-q78.webp)

Aufmerksame Zuhörer', NULL, 'Im Rahmen der Aktion "Lebendiger Adventskalender" der Pfarrei Heiliger Lukas, feierten wir unser Adventsfest am Sonntag, 19. Dezember auf der Kolpingwiese. Erika Maier hat unser Fenster am Jugendraum wunderschön gestaltet. Karin Becker las ', 'rueckblick/jahresprogramm', 0, '2021-12-20T00:00:00.000Z', 1, NULL, '2021-12-20T00:00:00.000Z', '2021-12-20T00:00:00.000Z', NULL);
