INSERT OR IGNORE INTO "Page" ("id", "slug", "title", "content", "metaTitle", "metaDesc", "parent", "sortOrder", "archiveDate", "published", "gallerySlug", "createdAt", "updatedAt", "authorId") VALUES ('legacypage_eb083a78ea3979f23fcdf803', 'rueckblick/jahresprogramm/2022-09-27-traditionelle-herbstwanderung-im-oktober', 'Traditionelle Herbstwanderung im Oktober', 'Am Samstag, 29. Oktober 2022 trafen sich 15 Personen am Bahnhof Ramsen und fuhren mit dem Zug nach Neustadt/ Wstr. und wanderten von dort über die "Hohe Loog" zum Pfälzerwaldhaus auf der Kalmit. Nach einer Mittagsrast führte die Wanderung nach Maikammer/ Kirrweiler zum Bahnhof. Von dort wurde die Heimreise wieder angetreten.

Die gesamte Wanderstrecke betrug ca. 14 km, mit 600 Höhenmetern.

