INSERT OR IGNORE INTO "Page" ("id", "slug", "title", "content", "metaTitle", "metaDesc", "parent", "sortOrder", "archiveDate", "published", "gallerySlug", "createdAt", "updatedAt", "authorId") VALUES ('legacypage_2b035e11fef6517b0d598d4a', 'rueckblick/jahresprogramm/2022-10-30-arbeitseinsatz-am-pfarrheim-2022', 'Arbeitseinsatz am Pfarrheim 2022', 'Am Samstag, 26. November trafen sich 25 Mitglieder zum traditionellen Arbeitseinsatz am Pfarrheim. Es wurden Büsche und Bäume geschnitten, Laub zusammengerecht. Das alles wurde dann von Lothar Kummermehr mit dem Traktor zur Grüngut Deponie gebracht. Die Frauen haben in dieser Zeit eine Grundreinigung in den beiden Küchen durchgeführt. Anschließend wurde dann gemeinsam zu Mittag gegessen.

Für diesen Einsatz ein herzliches Dankeschön.

![Arbeitseinsatz22](/images/legacy-v2/76/760674ae1384f900cad9f0fcf6c68dcb-w1600-q78.webp)

Ein sauberes Gelände, schön anzusehen.', NULL, 'Am Samstag, 26. November trafen sich 25 Mitglieder zum traditionellen Arbeitseinsatz am Pfarrheim. Es wurden Büsche und Bäume geschnitten, Laub zusammengerecht. Das alles wurde dann von Lothar Kummermehr mit dem Traktor zur Grüngut Deponie ', 'rueckblick/jahresprogramm', 0, '2022-10-30T00:00:00.000Z', 1, NULL, '2022-10-30T00:00:00.000Z', '2022-10-30T00:00:00.000Z', NULL);
