INSERT OR IGNORE INTO "Page" ("id", "slug", "title", "content", "metaTitle", "metaDesc", "parent", "sortOrder", "archiveDate", "published", "gallerySlug", "createdAt", "updatedAt", "authorId") VALUES ('legacypage_6dd2c88813c9c7c8cab4dbbd', 'rueckblick/jahresprogramm/2022-11-17-aelter-werden-auf-dem-land', '"Älter werden auf dem Land"', 'Die meisten Menschen möchten auch im Alter gerne so lange wie möglich in ihrem Haus
oder ihrer vertrauten Wohnung leben. Diesen Wunsch wollen die Gemeindeschwestern plus mit ihrem Angebot unterstützen: den Alltag erleichtern; Freizeitangebote schaffen; auf Wunsch Kontakte herstellen und beraten.

Tanja Loureiro von der Kreisverwaltung Donnersbergkreis hat am Donnerstag, 24. November sehr anschaulich über ihre Arbeit berichtet und Bewegungsübungen mit den anwesenden Gästen gemacht.
Themen des Abends waren auch: Die Notfalldose und die Notfallmappe. Was tun, wenn ich ins Krankenhaus muss? Was tun wenn der Notarzt kommt?

Ein Thema das auch Jüngere interessieren müsste.

![Alt werden daheim](/images/legacy-v2/42/42e27c1aec86583e29b78ad1e85f8376-w1600-q78.webp)

Reaktionsübung in der Gruppe', NULL, 'Die meisten Menschen möchten auch im Alter gerne so lange wie möglich in ihrem Haus oder ihrer vertrauten Wohnung leben. Diesen Wunsch wollen die Gemeindeschwestern plus mit ihrem Angebot unterstützen: den Alltag erleichtern; Freizeitangebo', 'rueckblick/jahresprogramm', 0, '2022-11-17T00:00:00.000Z', 1, NULL, '2022-11-17T00:00:00.000Z', '2022-11-17T00:00:00.000Z', NULL);
