INSERT OR IGNORE INTO "Page" ("id", "slug", "title", "content", "metaTitle", "metaDesc", "parent", "sortOrder", "archiveDate", "published", "gallerySlug", "createdAt", "updatedAt", "authorId") VALUES ('legacypage_d6894936db25e0c1f1afc87c', 'rueckblick/jahresprogramm/2022-11-24-adventsfeier-2022', 'Adventsfeier 2022', 'Am Sonntag, 18. Dezember feierten wir den 4. Advent mit dem Adventsfenster unserer Pfarrei, das von Erika und Ottmar Maier gestaltet wurde. Ca. 50 Mitglieder fanden trotz minus Temperaturen und Fußball WM Endspiel den Weg auf die Kolpingwiese. Unsere Feier wurde von der Blaskapelle musikalisch begleitet. Neben Geschichten um die Adventzeit, vorgetragen von Karin Becker, Heike Sattler und Lina Roos, dankte Bettina Schach allen die etwas zu diesem Fest beigetragen hatten und guten Wünschen an alle für das neue Jahr. Mit heißen Waffeln, Glühwein und Kinderpunsch konnten wir in gemütlicher Runde das Jahr 2022 ausklingen lassen. Die Spenden an diesem Abend werden von der Kolpingsfamilie auf 700 Euro aufgestockt und gehen an das Rehabilitationscentrum Dzherelo in Lemberg/ Ukraine.

![Adventsfeier1](/images/legacy-v2/e8/e8b15c76b38af1a920f9b7cb542d8d1b-w1600-q78.webp)

Das Adventsfenster  am 18. Dezember 2022

![Adventsfeier2](/images/legacy-v2/0a/0adb26f3d055127c8b00e00d05dfe5f6-w1600-q78.webp)

Die Kolpingskapelle konnte im Jugendraum die Adventslieder spielen, damit die Ventile nicht einfrieren.

![Adventsfeier3](/images/legacy-v2/39/39595ae9f0c9f38bf1c7cafddf0400fa-w1600-q78.webp)

Hier gab es die heißen Waffeln

![Adventsfeier4](/images/legacy-v2/f5/f51359970f7711d23c28271a68bb60f6-w1600-q78.webp)

Die Seniorenbank', NULL, 'Am Sonntag, 18. Dezember feierten wir den 4. Advent mit dem Adventsfenster unserer Pfarrei, das von Erika und Ottmar Maier gestaltet wurde. Ca. 50 Mitglieder fanden trotz minus Temperaturen und Fußball WM Endspiel den Weg auf die Kolpingwie', 'rueckblick/jahresprogramm', 0, '2022-11-24T00:00:00.000Z', 1, NULL, '2022-11-24T00:00:00.000Z', '2022-11-24T00:00:00.000Z', NULL);
