INSERT OR IGNORE INTO "Page" ("id", "slug", "title", "content", "metaTitle", "metaDesc", "parent", "sortOrder", "archiveDate", "published", "gallerySlug", "createdAt", "updatedAt", "authorId") VALUES ('legacypage_8176084cec2137121f0b12f7', 'rueckblick/jahresprogramm/2023-05-19-sing-mal-wieder-mit-walter', '"Sing mal wieder mit Walter"', 'Am Freitag, 07. Juli 2023 haben wir wieder auf der Kolpingwiese zusammen gesungen.

Walter Brauer  hatte ein schönes Programm zusammengestellt und uns dabei wie üblich mit seiner Gitarre begleitet.

Wegen der Trockenheit und der Brandgefahr haben wir kein Feuer  gemacht, was aber der guten Stimmung nicht schadete.

![Lieder mit Walter 2023 02](/images/legacy-v2/50/5017c801fceb86f8ed7537d9a851de05-w1600-q78.webp)

