INSERT OR IGNORE INTO "Page" ("id", "slug", "title", "content", "metaTitle", "metaDesc", "parent", "sortOrder", "archiveDate", "published", "gallerySlug", "createdAt", "updatedAt", "authorId") VALUES ('legacypage_40212f5d5248e1ad9e770215', 'rueckblick/jahresprogramm/2023-10-20-arbeitseinsatz-2023', 'Arbeitseinsatz 2023', 'Wir machten wieder unser Pfarrheim und die Kolpingwiese winterfest. Zu diesem Arbeitseinsatz waren 24 Mitglieder gekommen um zu helfen. Auch Lothar mit seinem Traktor musste zwei mal zur Gründeponie fahren. Anschließend gab es zum Mittagessen eine gute Suppe von Regina und Fleischkäsebrötchen von Peter.

