INSERT OR IGNORE INTO "Page" ("id", "slug", "title", "content", "metaTitle", "metaDesc", "parent", "sortOrder", "archiveDate", "published", "gallerySlug", "createdAt", "updatedAt", "authorId") VALUES ('legacypage_0e8e8f9ffa0e34f28f9f973e', 'rueckblick/jahresprogramm/2023-10-27-festzelt-abbau-2023', 'Festzelt Abbau 2023', 'Auch in diesem Jahre musste wieder zum Saisonende das Festzelt abgebaut werden. Die bewährten Kräfte erledigten dies an drei verschieden Tagen. Tag 1: Seitenwände von Hand reinigen und einlagern. Tag 2:  Dachbahnen herunterziehen, auf dem Boden abschrubben und noch einmal klar mit Wasser abstrahlen. Danach bei Bruno und bei Kolping senkrecht aufhängen zum Trocknen. Tag 3: Dachbahnen abnehmen, zusammenrollen und einlagern.

![Zelt abbauen 05](/images/legacy-v2/1d/1dfd4561c295511c053e930f4f73ea42-w1600-q78.webp)

![Zelt abbauen 06](/images/legacy-v2/9e/9e749e639033f12a8542831bb4b246a1-w1600-q78.webp)

![Zelt abbauen 08](/images/legacy-v2/66/663097e8ee346ebab67d0f932d3dc36b-w1600-q78.webp)

![Zelt abbauen 08a](/images/legacy-v2/4e/4ee9125f5ae795f6434005f9fc4981c5-w1600-q78.webp)

![Zelt abbauen 09](/images/legacy-v2/79/799b1ef13cc3642f6e378649262c93d9-w1600-q78.webp)', NULL, 'Auch in diesem Jahre musste wieder zum Saisonende das Festzelt abgebaut werden. Die bewährten Kräfte erledigten dies an drei verschieden Tagen. Tag 1: Seitenwände von Hand reinigen und einlagern. Tag 2: Dachbahnen herunterziehen, auf dem Bo', 'rueckblick/jahresprogramm', 0, '2023-10-27T00:00:00.000Z', 1, NULL, '2023-10-27T00:00:00.000Z', '2023-10-27T00:00:00.000Z', NULL);
