INSERT OR IGNORE INTO "Page" ("id", "slug", "title", "content", "metaTitle", "metaDesc", "parent", "sortOrder", "archiveDate", "published", "gallerySlug", "createdAt", "updatedAt", "authorId") VALUES ('legacypage_263313c256aa41e4748fea3c', 'rueckblick/jahresprogramm/2024-06-26-nachruf-auf-ehrenpraeses-werner-kilian', 'Nachruf auf Ehrenpräses Pfarrer Werner Kilian', 'Am Dienstagnachmittag, 25. Juni 2024 ist Pfr. Werner Kilian im Westpfalz - Klinikum - Kaiserslautern im Alter von 80 Jahren für immer eingeschlafen.

