INSERT OR IGNORE INTO "Page" ("id", "slug", "title", "content", "metaTitle", "metaDesc", "parent", "sortOrder", "archiveDate", "published", "gallerySlug", "createdAt", "updatedAt", "authorId") VALUES ('legacypage_ed1bbdf199856d7f4dd54ee4', 'rueckblick/jahresprogramm/2024-10-03-die-e-bikegruppe-der-kf', 'Die E-Bikegruppe der KF', 'Bei schönem Wetter wurde wieder eine Fahrt mit der E-Bikegruppe durchgeführt. Zunächst ging es hinter dem Kleehof über die mittlerweile bekannte Berg und Talstrecke Richtung Süden. Nach der Autobahn, bergab zum Isenachweiher. Nach einer kurzen Rast kamen wir ins Bad Dürkheimer Tal. Die Mittagspause legten wir im Waldschlösschen ein. Nach einer kräftigen Stärkung ging die Fahrt weiter über Bad Dürkheim, Freinsheim, Grünstadt, Asselheim dann durchs Eistal wieder nach Ramsen.

Die Gesamtfahrstecker der 9 Teilnemer wurde mit ca. 60 Kilometer gemessen.

![Ebiketour2024 01](/images/legacy-v2/8e/8e12de9b4646a4452e592ce6306b80fc-w1600-q78.webp)

Gruppenbild der 9 Teilnehmer (Bernd fehlt als Fotograf)

![Ebiketour2024 02](/images/legacy-v2/b9/b918760c691970a862a341668c650ab1-w1600-q78.webp)

Mittagsrast im Waldschlösschen', NULL, 'Bei schönem Wetter wurde wieder eine Fahrt mit der E-Bikegruppe durchgeführt. Zunächst ging es hinter dem Kleehof über die mittlerweile bekannte Berg und Talstrecke Richtung Süden. Nach der Autobahn, bergab zum Isenachweiher. Nach einer kur', 'rueckblick/jahresprogramm', 0, '2024-10-03T00:00:00.000Z', 1, NULL, '2024-10-03T00:00:00.000Z', '2024-10-03T00:00:00.000Z', NULL);
