INSERT OR IGNORE INTO "Page" ("id", "slug", "title", "content", "metaTitle", "metaDesc", "parent", "sortOrder", "archiveDate", "published", "gallerySlug", "createdAt", "updatedAt", "authorId") VALUES ('legacypage_23731be42aee9a3b75dc2546', 'rueckblick/jahresprogramm/2024-10-23-jesus-von-nazareth-vortrag', 'Jesus von Nazareth – zwischen Glaubenstradition und historischen Fakten', '## Jesus von Nazareth ist eine der einflussreichsten Gestalten der Weltgeschichte – doch wer war er wirklich?

In dem Vortrag "Jesus von Nazareth – Zwischen Glaubenstradition und historischen Fakten" wurde das Spannungsfeld zwischen religiösen Deutungen und historischen Erkenntnissen beleuchtet.

![Jesus](/images/legacy-v2/78/78ff26402321fa6dacfd2293ce4f3aad-w1600-q78.webp)', NULL, 'Jesus von Nazareth ist eine der einflussreichsten Gestalten der Weltgeschichte – doch wer war er wirklich? In dem Vortrag "Jesus von Nazareth – Zwischen Glaubenstradition und historischen Fakten" wurde das Spannungsfeld zwischen religiösen ', 'rueckblick/jahresprogramm', 0, '2024-10-23T00:00:00.000Z', 1, NULL, '2024-10-23T00:00:00.000Z', '2024-10-23T00:00:00.000Z', NULL);
