INSERT OR IGNORE INTO "Page" ("id", "slug", "title", "content", "metaTitle", "metaDesc", "parent", "sortOrder", "archiveDate", "published", "gallerySlug", "createdAt", "updatedAt", "authorId") VALUES ('legacypage_00bfb8d2f1de6fba9e479c67', 'rueckblick/jahresprogramm/2025-04-22-bezirksmaiandacht-2025', 'Bezirksmaiandacht 2025 an der Mariengrotte', '## Maiandacht des Bezirks Grünstadt/ Frankenthal

Die Bezirksmaiandacht fand am Freitag, 23. Mai 2025 in Ramsen an der Mariengrotte statt. Musikalisch wurde diese Andacht wieder von der Kolpingskapelle begleitet.

Anschließend trafen wir uns im Pfarrheim bei einem gemütliches Beisammensein mit verschiedenen Bowlen.

![Grotte](/images/legacy-v2/e0/e0e34fe2c73ba122d82e82c31ef762cd-w1600-q78.webp)

Die Mariengrotte 1973 von der Kolpingsfamilie erbaut', NULL, 'Maiandacht des Bezirks Grünstadt/ Frankenthal Die Bezirksmaiandacht fand am Freitag, 23. Mai 2025 in Ramsen an der Mariengrotte statt. Musikalisch wurde diese Andacht wieder von der Kolpingskapelle begleitet. Anschließend trafen wir uns im ', 'rueckblick/jahresprogramm', 0, '2025-04-22T00:00:00.000Z', 1, NULL, '2025-04-22T00:00:00.000Z', '2025-04-22T00:00:00.000Z', NULL);
